package main

import (
	"fmt"
	"sync"
	"testing"
	"time"
)

func TestProbeGetOrCreate(t *testing.T) {
	store := NewStore(time.Minute)
	now := time.Unix(1000, 0)
	store.now = func() time.Time { return now }

	s, created := store.GetOrCreate("s1", "alice")
	if !created || s.User != "alice" {
		t.Fatalf("first: created=%v user=%s", created, s.User)
	}

	// Second caller with a different user: gets the EXISTING session.
	s2, created2 := store.GetOrCreate("s1", "bob")
	if created2 {
		t.Fatal("second call must not create")
	}
	if s2.User != "alice" {
		t.Fatalf("existing session user = %q, want alice", s2.User)
	}
	if store.Len() != 1 {
		t.Fatalf("len = %d, want 1", store.Len())
	}

	// Expired: replaced, created=true.
	now = time.Unix(2000, 0)
	s3, created3 := store.GetOrCreate("s1", "carol")
	if !created3 || s3.User != "carol" {
		t.Fatalf("expired path: created=%v user=%s", created3, s3.User)
	}

	// Atomicity smoke: hammer GetOrCreate from 8 goroutines; exactly one
	// create per fresh id wins per round.
	store2 := NewStore(time.Minute)
	for round := 0; round < 20; round++ {
		id := fmt.Sprintf("shared-%d", round)
		results := make(chan bool, 8)
		var wg sync.WaitGroup
		for g := 0; g < 8; g++ {
			wg.Add(1)
			go func() {
				defer wg.Done()
				_, wasCreated := store2.GetOrCreate(id, "shared")
				results <- wasCreated
			}()
		}
		wg.Wait()
		close(results)
		createdCount := 0
		for wasCreated := range results {
			if wasCreated {
				createdCount++
			}
		}
		if createdCount != 1 {
			t.Fatalf("round %d: %d creates, want exactly 1 (atomicity broken)", round, createdCount)
		}
	}
}
EOF
go test -race -count=1 . ; rc=$? ; rm -f probe_goc_test.go ; exit $rc

